-- TomoModForever 1.2.0 release notes.

TomoMod_RegisterLocale("enUS", {
    ["wn_120_mail"] = "New - Comfort > Mail: TomoMail joins TomoModForever in the Forever colours. Inbox with filters and \"Take all\", send tab, contacts (your characters, guild, recent), send to every alt and autocomplete. Uses the existing Mail skin switch.",
    ["wn_120_flight"] = "New - Adventure > Flight timer: a bar with the destination and time left during flights. Each route is measured the first time you fly it, then counted down; routes made of known pieces get an estimate (≈).",
    ["wn_120_flightmap"] = "New - The flight map tooltip shows how long each flight takes. Learned times are shared by all your characters.",
    ["wn_120_res"] = "New - Adventure > Adventure comforts: accept resurrections automatically (optionally not while the caster is in combat).",
    ["wn_120_errors"] = "New - Hide the red error text and its voice, always or in combat only, keeping important messages if you want.",
    ["wn_120_train"] = "New - \"Train all\" button at trainers: learns everything you can afford, cheapest first.",
    ["wn_120_camera"] = "New - Max camera zoom, no drunken haze and no grey death screen. Unticking restores your previous values.",
})

